actions.script:
// Rewrites floridaparcels.com owner search rows into fields C-S-S can match.
// Each row carries the owners as "LAST FIRST MIDDLE", joint owners joined by
// "&" (a later owner may drop the shared last name: "SMITH JOHN A & MARY B"),
// followed by the mailing address on separate lines. The physical address is
// a street link plus a "CITY, ST ZIP" line. C-S-S reads names first-last and
// addresses as one "STREET, CITY, ST ZIP" string, so this appends hidden
// spans carrying those forms for the extract to read.
//
// Called as function (userProfile, root).

// Words that follow an owner's name but are not part of it.
const NON_NAME_WORDS = new Set([
  "TR",
  "TRS",
  "TRUSTEE",
  "TRUSTEES",
  "ETAL",
  "ET",
  "AL",
  "LE",
  "JTWROS",
  "H/W",
  "H/E",
  "W/H",
  "EST",
  "ESTATE",
  "REV",
  "LIV",
  "TRUST",
]);
const SUFFIXES = new Set(["JR", "SR", "II", "III", "IV", "V"]);

function words(text) {
  return text
    .toUpperCase()
    .replace(/[.,]/g, " ")
    .trim()
    .split(/\s+/)
    .filter(Boolean);
}

// The cell's text split at <br>, trimmed, empty lines dropped.
function lines(cell) {
  return cell.innerHTML
    .split(/<br\s*\/?>/i)
    .map((html) => {
      const div = root.createElement("div");
      div.innerHTML = html;
      return div.textContent.replace(/\s+/g, " ").trim();
    })
    .filter(Boolean);
}

// Turns one owner segment into "FIRST MIDDLE LAST SUFFIX". A segment that
// starts with the user's first name is taken to share the first owner's last
// name; any other segment is read last name first.
function ownerName(segment, sharedLast, userFirst, userLast) {
  const tokens = words(segment).filter((w) => !NON_NAME_WORDS.has(w));
  if (!tokens.length) return "";
  const suffix = SUFFIXES.has(tokens[tokens.length - 1]) ? tokens.pop() : "";
  let last;
  let rest;
  if (userLast && tokens.join(" ").indexOf(userLast + " ") === 0) {
    last = userLast;
    rest = tokens.slice(userLast.split(" ").length);
  } else if (sharedLast && userFirst && tokens[0] === userFirst) {
    last = sharedLast;
    rest = tokens;
  } else {
    last = tokens[0];
    rest = tokens.slice(1);
  }
  return [...rest, last, suffix].filter(Boolean).join(" ");
}

// Picks the owner whose first name matches the user's, else the first owner.
function bestOwner(ownerLine) {
  const userFirst = ((userProfile && userProfile.firstName) || "")
    .toUpperCase()
    .trim();
  const userLast = ((userProfile && userProfile.lastName) || "")
    .toUpperCase()
    .trim();
  const segments = ownerLine
    .split("&")
    .map((s) => s.trim())
    .filter(Boolean);
  const sharedLast = segments.length ? words(segments[0])[0] : "";
  const names = segments
    .map((s) => ownerName(s, sharedLast, userFirst, userLast))
    .filter(Boolean);
  const match = names.find((n) => userFirst && words(n).includes(userFirst));
  return match || names[0] || "";
}

// "STREET" plus "CITY, ST ZIP" as one address. Extra leading lines (c/o and
// the like) are dropped, since the street is the line before the city line.
function address(addressLines) {
  if (addressLines.length < 2) return "";
  const cityLine = addressLines[addressLines.length - 1];
  const street = addressLines[addressLines.length - 2];
  return street + ", " + cityLine;
}

function hiddenSpan(field, text) {
  const span = root.createElement("span");
  span.setAttribute("data-pir", field);
  span.style.display = "none";
  span.textContent = text;
  return span;
}

for (const row of root.querySelectorAll("#property_listing tr[data-url]")) {
  const physical = row.cells[1];
  const owner = row.cells[2];
  if (!physical || !owner) continue;

  const ownerLines = lines(owner);
  if (!ownerLines.length) continue;

  const holder = root.createElement("div");
  holder.appendChild(hiddenSpan("name", bestOwner(ownerLines[0])));
  const physicalAddress = address(lines(physical));
  if (physicalAddress)
    holder.appendChild(hiddenSpan("address", physicalAddress));
  const mailingAddress = address(ownerLines.slice(1));
  if (mailingAddress && mailingAddress !== physicalAddress) {
    holder.appendChild(hiddenSpan("address", mailingAddress));
  }
  owner.appendChild(holder);
}
